      warn "Failed to verify signature of unorphaned blobless block",
        blck = shortLog(forkyBlck), error = res.error()
      continue
    let cres = self.dataColumnQuarantine[].popSidecars(forkyBlck.root, forkyBlck)
    if cres.isSome:
      self.enqueueBlock(
